for _ in range(int(input())):
	n = int(input())
	A = list(map(int, input().split()))
	B = list(map(int, input().split()))
	count = 0
	d = {}
	for i in range(n):
		if (B[i], A[i]) in d:
			count += d[B[i], A[i]]
		if (A[i], B[i]) in d:
			d[A[i], B[i]] += 1
		else:
			d[A[i], B[i]] = 1
	print(count)
